design.compositionCss:
/* Midnight Marquee: original late-screening composition. */
.shell{display:grid;grid-template-columns:216px minmax(0,1fr)}
.sidebar{display:flex;flex-direction:column;position:sticky;top:0;height:100dvh;padding:28px 16px;gap:16px;border:0;border-right:1px solid var(--weekly-soft);overflow-y:auto}
.brand{margin:0 0 18px;gap:10px}
.brand strong{font-family:var(--body);font-size:14px;font-weight:600;line-height:1.3}
.brand small{font-size:10px}
.sidebar nav{display:grid;grid-template-columns:minmax(0,1fr);gap:4px}
.nav-item{display:flex;align-items:center;gap:12px;border:0;border-radius:9px;min-height:45px;padding:11px 12px;font-family:var(--body);font-size:12px;letter-spacing:0}
.nav-item span{font-family:var(--condensed);font-size:17px;min-width:20px;line-height:1}
.sidebar-foot{display:grid;gap:8px;border:0;margin-top:auto;padding-top:20px}
.sidebar-foot .quiet{border-radius:8px;text-align:left}
main{padding:0 34px 72px;max-width:1580px;margin:auto}
.topbar{min-height:118px;padding:27px 0;margin-bottom:26px;border:0}
.topbar h1{font-family:var(--body);font-weight:600;font-size:clamp(27px,3vw,39px);line-height:1.25;letter-spacing:-.04em;text-transform:none}
.eyebrow,.topbar .eyebrow{color:var(--weekly-mark)}
.primary,.quiet{border-radius:8px;min-height:44px}
.primary{background:var(--acid);color:var(--stage);border-color:var(--acid)}
.quiet{background:var(--panel);color:var(--ink);border-color:var(--weekly-soft)}
.panel,.module,.resource,.phase,.evidence-card,.production,.daily-review,.stat-card:nth-child(n),.cinema-film{padding:24px;border:1px solid var(--weekly-soft);border-radius:15px;box-shadow:none}
.panel h2,.intro-panel h2{font-family:var(--body);font-weight:600;font-size:24px;line-height:1.35;letter-spacing:-.035em;text-transform:none;border:0;padding-bottom:0}
.panel .eyebrow{color:var(--weekly-mark)}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.poster-focus{grid-column:1/4;grid-row:1/4;min-height:590px;padding:36px;display:flex;flex-direction:column;align-items:start;border:1px solid var(--weekly-soft);border-radius:20px}
.poster-focus h2{font-family:var(--condensed);font-size:clamp(65px,7.2vw,100px);line-height:1.04;letter-spacing:-.015em;max-width:100%;margin:0 0 20px;text-decoration:none}
.poster-focus h2 span{width:fit-content;max-width:100%;font-family:var(--condensed);font-size:1em;line-height:1.08;letter-spacing:-.015em;transform:none;padding:4px 12px 8px;margin:10px 0 0;border-radius:6px}
.poster-focus .hero-script{font-family:var(--script);font-size:30px!important;line-height:1.3;margin:0 0 22px}
.poster-focus .cinema-scene{width:57%;right:-9%;top:20%;opacity:.42;transform:rotate(-4deg)}
.poster-focus .hero-star{width:42px;height:42px;top:26px;right:24px}
.poster-focus .progress-wrap{max-width:340px;margin-top:28px}
.hero-grid .stat-card{grid-column:4;grid-row:auto;min-height:160px;display:flex;flex-direction:column;align-items:start;padding:24px 20px;border:1px solid var(--weekly-soft);border-radius:14px;background:var(--panel)}
.hero-grid .stat-card strong{font-family:var(--condensed);font-size:46px;font-weight:400;line-height:1;margin:16px 0 8px;letter-spacing:0}
.hero-grid .stat-card span,.hero-grid .stat-card small{font-size:10px;line-height:1.5}
.studio-programme{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:26px 0 32px;border:0}
.studio-programme button{border:1px solid var(--weekly-soft)!important;border-left:4px solid var(--weekly-mark)!important;border-radius:12px;min-height:112px;padding:22px!important;background:var(--panel);box-shadow:none}
.studio-programme span{font-family:var(--body);font-size:17px;font-weight:600;line-height:1.4;letter-spacing:-.02em}
.syllabus-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.module{border-top:3px solid var(--weekly-mark)}
.module h3{font-family:var(--condensed);font-size:27px;line-height:1.3;letter-spacing:0;text-transform:none}
.module-head small{font-family:var(--body);font-style:normal;font-size:11px;line-height:1.6}
.topic{font-size:13px;line-height:1.6}
.roadmap{display:grid;columns:auto;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.phase:nth-child(n){display:block;margin:0!important;min-height:240px;border:1px solid var(--weekly-soft);border-left:4px solid var(--weekly-mark);border-radius:14px;padding:26px}
.phase h3{font-family:var(--condensed);font-size:29px;line-height:1.2;letter-spacing:0;margin:14px 0}
.phase small{font-family:var(--body);font-size:10px;letter-spacing:.12em}
.phase ul{margin-top:16px}
.resource-list{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.resource{display:block;padding:26px;border:1px solid var(--weekly-soft);border-bottom:3px solid var(--weekly-mark);border-radius:14px}
.resource h3{font-family:var(--body);font-size:18px;font-weight:600;line-height:1.4;letter-spacing:-.02em}
.resource div{margin-bottom:16px}
.evidence-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.evidence-card{border-top:3px solid var(--weekly-mark)}
.evidence-card label{font-family:var(--body);font-size:15px;line-height:1.5}
.cinema-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.cinema-film{padding:20px}
.film-cover{min-height:310px;border:0;border-radius:10px;box-shadow:none;background:var(--weekly-soft);padding:24px 18px}
.cinema-film .film-cover h3{font-family:var(--script);font-size:44px;line-height:1.02;font-weight:600;text-transform:none;letter-spacing:-.035em}
.film-cover h3 small,.cover-caption{color:var(--ink)}
.cover-caption{font-size:9px;letter-spacing:.08em}
.cinema-intro{border:1px solid var(--weekly-soft);border-radius:18px;padding:32px}
.cinema-intro h2{font-family:var(--condensed);font-size:clamp(38px,4.5vw,60px);line-height:1.15;letter-spacing:0}
.cinema-source-note,.cinema-credits,.meta,.studio-footer{color:var(--ink)}
.journal-masthead{padding:30px 0;border-bottom:1px solid var(--weekly-soft)}
.journal-masthead h2{font-family:var(--condensed);font-size:clamp(72px,9vw,120px);line-height:1.15;letter-spacing:0}
.journal-masthead h2 em{font-family:var(--script);font-style:italic;font-size:.85em;line-height:1.15;letter-spacing:-.035em;background:var(--panel);color:var(--ink);padding:0 14px 8px;border-radius:10px;transform:none}
.journal-seal{border:1px solid var(--weekly-mark);border-radius:50%;background:var(--panel);transform:rotate(-6deg)}
.journal-workbench{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px}
.journal-bridge{transform:none}
.journal-section-title{border-top:1px solid var(--weekly-soft)}
.journal-section-title h2{font-family:var(--body);font-size:25px;font-weight:600;line-height:1.3;letter-spacing:-.03em}
#view-journal .journal-deck{gap:22px}
.diary-card:not(.poster-card){transform:none;margin:0;border:1px solid var(--weekly-soft);border-radius:14px;padding:24px;box-shadow:none}
.diary-card:not(.poster-card) h3{font-family:var(--script);font-size:48px;line-height:1.1;text-transform:none}
#view-journal .diary-card.poster-card{border-radius:12px}
.journal-empty{border-color:var(--weekly-soft);border-radius:14px}
.journal-empty h3{font-size:44px;line-height:1.2}
.form-panel input,.form-panel select,.form-panel textarea,.filter-row input,.filter-row select{border:1px solid var(--weekly-soft);border-radius:8px;background:var(--stage);color:var(--ink)}
.filter-row{border:1px solid var(--weekly-soft);border-radius:12px;background:var(--panel)}
.tag{border-radius:5px}
@media(max-width:1100px) and (min-width:761px){
.shell{grid-template-columns:190px minmax(0,1fr)}
.sidebar nav{grid-template-columns:minmax(0,1fr)}
main{padding:0 24px 64px}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr))}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:480px}
.hero-grid .stat-card{grid-column:auto;min-height:130px}
.cinema-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.journal-workbench{grid-template-columns:minmax(0,1fr)}
}
@media(max-width:760px){
.shell{display:block}
.sidebar{display:block;position:relative;height:auto;padding:20px;border:0;border-bottom:1px solid var(--weekly-soft)}
.brand{margin:0}
.sidebar-foot{display:flex;flex-wrap:wrap;margin-top:14px;padding:0}
.sidebar-foot .quiet{font-size:10px;padding:10px}
main{padding:0 20px 56px}
.topbar{padding:24px 0;margin-bottom:20px;min-height:0}
.topbar h1{font-size:28px;line-height:1.3;letter-spacing:-.035em}
.top-actions{margin-top:14px}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:500px;padding:28px 22px;border:1px solid var(--weekly-soft);border-radius:18px}
.poster-focus h2{font-size:clamp(51px,14.2vw,75px);line-height:1.1;letter-spacing:-.015em}
.poster-focus h2 span{padding:3px 8px 6px}
.poster-focus .hero-script{font-size:25px!important}
.poster-focus .cinema-scene{width:78%;right:-18%;top:15%;opacity:.3}
.poster-focus .hero-star{width:30px;height:30px;top:25px;right:20px}
.hero-grid .stat-card{grid-column:auto;grid-row:auto;min-height:126px;padding:16px 10px;border:1px solid var(--weekly-soft);border-radius:12px}
.hero-grid .stat-card strong{font-size:33px}
.hero-grid .stat-card span,.hero-grid .stat-card small{font-size:9px;letter-spacing:0}
.studio-programme,.syllabus-grid,.roadmap,.resource-list,.evidence-grid,.cinema-grid{grid-template-columns:minmax(0,1fr);gap:16px}
.studio-programme button{min-height:98px;padding:22px!important}
.studio-programme span{font-size:17px}
.panel,.module,.resource,.evidence-card,.production,.daily-review,.cinema-film{padding:22px}
.panel h2,.intro-panel h2{font-size:23px;line-height:1.35}
.phase:nth-child(n){min-height:0;padding:24px}
.phase h3{font-size:28px}
.resource h3{font-size:17px}
.film-cover{min-height:280px}
.cinema-film .film-cover h3{font-size:42px;line-height:1.1}
.journal-masthead h2{font-size:clamp(48px,13.4vw,70px);line-height:1.2;overflow-wrap:anywhere}
.journal-masthead h2 em{font-size:.9em;line-height:1.2;padding:0 8px 5px}
#view-journal .journal-workbench{grid-template-columns:minmax(0,1fr)}
#view-journal .journal-workbench :is(.form-panel,.journal-bridge){min-width:0;max-width:100%}
#view-journal .journal-workbench :is(form,details,label,small,p,div){min-width:0;max-width:100%;overflow-wrap:anywhere}
#view-journal .form-panel,#view-journal .form-row{grid-template-columns:minmax(0,1fr)}
#view-journal .panel-head{flex-direction:column;align-items:start}
#view-journal .journal-workbench :is(input,select,textarea){min-width:0;max-width:100%;width:100%;box-sizing:border-box}
#view-journal .journal-check input{flex-shrink:0}
#view-journal .journal-workbench :is(button,a){max-width:100%;white-space:normal;overflow-wrap:anywhere}
#view-journal .journal-deck{grid-template-columns:minmax(0,1fr);width:100%}
#view-journal .diary-card:nth-child(n){transform:none;box-shadow:none}
#view-journal .journal-empty{min-width:0;padding:34px 14px}
#view-journal .journal-empty h3{font-size:38px;overflow-wrap:anywhere}
#view-journal .journal-watch-shelf{min-width:0;overflow-wrap:anywhere}
#view-journal .watch-ticket{flex-wrap:wrap}
}
